    public function fetch_tickers(?array $symbols = null, $params = array ()): PromiseInterface {
        return Async\async(function () use ($symbols, $params) {
            /**
             * fetches 24 hour price statistics for multiple OTC markets
             * @see https://swapwallet.app/api/v2/market/crypto/stats
             * @param {string[]} [$symbols] unified $symbols, all markets are returned if null
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {array} a dictionary of $ticker structures indexed by symbol
             */
            Async\await($this->load_markets());
            $symbols = $this->market_symbols($symbols);
            $response = Async\await($this->publicGetMarketCryptoStats ($params));
            $tickers = $this->safe_dict($response, 'result', array());
            $ids = is_array($tickers) ? array_keys($tickers) : array();
            $result = array();
            for ($i = 0; $i < count($ids); $i++) {
                $id = $ids[$i];
                $ticker = $this->parse_ticker($tickers[$id]);
                $result[$ticker['symbol']] = $ticker;
            }
            return $this->filter_by_array_tickers($result, 'symbol', $symbols);
        }) ();
    }

    public function fetch_ticker(string $symbol, $params = array ()): PromiseInterface {
        return Async\async(function () use ($symbol, $params) {
            /**
             * fetches 24 hour price statistics for a single OTC $market
             * @see https://swapwallet.app/api/v2/market/crypto/stats
             * @param {string} $symbol unified $market $symbol
             * @param {array} [$params] extra parameters specific to the exchange API endpoint
             * @return {array} a ticker structure
             */
            Async\await($this->load_markets());
            $market = $this->market($symbol);
            $tickers = Async\await($this->fetch_tickers([ $market['symbol'] ], $params));
            return $tickers[$market['symbol']];
        }) ();
    }

    public function parse_ticker($ticker, ?array $market = null): array {
